/*
Theme Name: Careful Shopper — Twenty Twenty-Five Child
Template: twentytwentyfive
Author: Careful Shopper demo
Description: MHTML-inspired editorial styling for the mosquito protection guide.
Version: 1.1.0
Text Domain: careful-shopper
*/

:root{
 --cs-green:#075C37;
 --cs-deep:#06472D;
 --cs-gold:#B78B2E;
 --cs-ink:#14251C;
 --cs-muted:#66766B;
 --cs-paper:#FBFAF6;
 --cs-line:#DCE3DA;
 --cs-soft:#EEF3ED;
 --cs-cream:#F5F0E6;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--cs-paper);color:var(--cs-ink);font-family:Verdana,Geneva,Arial,sans-serif;font-size:16px;line-height:1.7}
a{color:var(--cs-green);text-underline-offset:.16em;text-decoration-thickness:1px}
a:hover{color:var(--cs-deep)}
a:focus-visible,button:focus-visible{outline:3px solid var(--cs-gold);outline-offset:3px}
main,.wp-site-blocks main{width:min(1120px,calc(100% - 40px));margin:32px auto 56px}
.zone{position:relative;overflow:hidden;margin:0 0 24px;padding:clamp(24px,4vw,40px);border:1px solid var(--cs-line);border-radius:22px;background:#fff;box-shadow:0 8px 28px rgba(20,37,28,.045)}
.site-header{padding:20px 24px;background:var(--cs-paper);border-bottom:1px solid var(--cs-line)}
.header-inner{width:min(1120px,100%);margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:24px}
.brand{display:flex;align-items:center;gap:12px;min-width:12rem;color:var(--cs-green);text-decoration:none}
.brand-mark{width:48px;height:48px;display:grid;place-items:center;flex:0 0 48px;border:1px solid #b9d0c1;border-radius:15px 50% 15px 50%;background:var(--cs-soft);font-size:20px;font-weight:700}
.brand-copy{display:flex;flex-direction:column;line-height:1.25}
.brand-name{color:var(--cs-green);font-size:1.3rem;font-weight:700}
.tagline{color:var(--cs-muted);font-size:.9rem}
.desktop-nav{display:flex;align-items:center;gap:20px;flex-wrap:wrap}
.desktop-nav a,.nav-unavailable{font-size:.92rem;font-weight:700}
.nav-unavailable{color:var(--cs-muted);text-decoration:underline;text-decoration-style:dotted;text-underline-offset:4px}
.menu-button{display:none;min-height:44px;padding:10px 16px;border:0;border-radius:8px;background:var(--cs-green);color:#fff;font:700 1rem Verdana,Geneva,Arial,sans-serif}
.mobile-nav{display:none;max-width:1120px;margin:16px auto 0;padding:16px;border:1px solid var(--cs-line);border-radius:14px;background:#fff}
.mobile-nav.open{display:flex;flex-direction:column;gap:14px}
.mobile-nav a,.mobile-nav .nav-unavailable{display:block}
.hero{padding:clamp(32px,6vw,64px);border:0;border-radius:28px;background:var(--cs-green);color:#fff;box-shadow:0 18px 42px rgba(7,92,55,.16)}
.hero:after{content:"";position:absolute;right:-100px;top:-150px;width:360px;height:360px;border:1px solid rgba(255,255,255,.2);border-radius:50%;box-shadow:0 0 0 28px rgba(255,255,255,.045),0 0 0 58px rgba(255,255,255,.03);pointer-events:none}
.hero>*{position:relative;z-index:1;max-width:820px}
.hero a,.hero .breadcrumb{color:#fff}
.breadcrumb{margin:0 0 12px;color:rgba(255,255,255,.82);font-size:.9rem}
h1{margin:8px 0 18px;color:#fff;font-size:clamp(2rem,4.4vw,3.25rem);line-height:1.14;letter-spacing:-.025em}
h2{margin:0 0 18px;color:var(--cs-green);font-size:clamp(1.35rem,2.4vw,1.8rem);line-height:1.25}
h3{margin:12px 0 8px;color:var(--cs-deep);font-size:1.12rem;line-height:1.35}
p{margin:0 0 16px}
p:last-child{margin-bottom:0}
.byline{color:rgba(255,255,255,.84);margin-bottom:14px}
.short-answer{padding:16px 18px;border-left:4px solid var(--cs-gold);border-radius:0 10px 10px 0;background:rgba(255,255,255,.11)}
.disclosure{padding:20px 24px;border:1px solid #e7d8b4;border-radius:14px;background:#F8F1DF;color:#49391C;font-size:1rem;line-height:1.6}
.education{background:#fff}
.bite-photo{display:block;width:100%;max-width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:14px}
.photo-credit{width:100%;max-width:100%;margin:0 0 16px;color:var(--cs-muted);text-align:center;font-size:.82rem}
.education-second{clear:both;padding-top:8px}
.layer-zone,.pairing-zone{background:var(--cs-soft);border-color:#d1dfd4}
.layer-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.layer-card{padding:20px;border:1px solid #d5e1d7;border-radius:14px;background:#fff;box-shadow:0 4px 14px rgba(20,37,28,.035)}
.layer-card h3{margin:0 0 8px;color:var(--cs-green);font-size:1.2rem}
.layer-card p{margin:0}
.layer-close{margin:18px 0 0;padding:14px 16px;border-radius:10px;background:rgba(255,255,255,.72);color:var(--cs-ink)}
.comparison{background:#fff}
.table-wrap{max-width:100%;overflow-x:auto;border:1px solid #b9c8bd;border-radius:12px}
table{width:100%;min-width:42rem;border-collapse:collapse;color:var(--cs-ink);font-size:.95rem}
th,td{padding:14px 13px;border-bottom:1px solid var(--cs-line);text-align:left;vertical-align:top}
th{background:var(--cs-soft);color:var(--cs-deep);font-weight:700}
tbody tr:nth-child(even){background:#FCFDFB}
.barrier-zone{border-color:#e6dece;background:var(--cs-cream)}
.card-zone-intro{margin:0 0 20px}
.product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));justify-content:center;gap:18px}
.product-card{display:flex;flex-direction:column;align-items:stretch;width:100%;max-width:100%;padding:18px;border:1px solid #e0ded4;border-radius:16px;background:#fff;box-shadow:0 6px 20px rgba(57,40,17,.05)}
.product-window{display:flex;width:100%;min-height:150px;aspect-ratio:16/10;align-items:center;justify-content:center;border:1px dashed #9bb5a2;border-radius:10px;background:#FBFCFA;color:var(--cs-muted);text-align:center;text-decoration:none;font-size:.9rem}
.product-card h3{margin:14px 0 10px}
.caption-line{margin:0 0 8px;color:var(--cs-ink);font-size:.93rem}
.caption-line strong{color:var(--cs-deep)}
.product-cta{display:flex;align-items:center;justify-content:center;min-height:46px;margin-top:auto;padding:12px 16px;border-radius:8px;background:var(--cs-green);color:#fff;text-align:center;text-decoration:none;font-size:.92rem;font-weight:700;letter-spacing:.025em}
.product-cta:hover{background:var(--cs-deep);color:#fff}
.card-spacer{height:12px;flex:1 0 12px}
.pairing-zone .product-card{background:#fff}
.footer-zone{background:var(--cs-deep);color:#fff;border:0}
.footer-zone h2,.footer-zone h3{color:#fff}
.footer-zone a,.footer-zone .nav-unavailable{color:#fff}
.footer-nav{display:flex;gap:20px;flex-wrap:wrap;margin:22px 0}
.footer-nav a,.footer-nav .nav-unavailable{font-size:.92rem}
.footer-note{margin:14px 0 0;padding-top:14px;border-top:1px solid rgba(255,255,255,.35);color:rgba(255,255,255,.85);font-size:.88rem}
.copyright{margin:18px 0 0;color:rgba(255,255,255,.8);font-size:.88rem}
@media(max-width:760px){
 .header-inner{align-items:center}
 .desktop-nav{display:none}
 .menu-button{display:inline-flex;align-items:center;justify-content:center}
 main,.wp-site-blocks main{width:calc(100% - 24px);margin:18px auto 36px}
 .zone{padding:22px;margin-bottom:16px;border-radius:16px}
 .hero{padding:30px 24px;border-radius:22px}
 .hero:after{width:220px;height:220px;right:-100px;top:-90px}
 .mobile-nav{width:calc(100% - 32px)}
 .layer-grid{grid-template-columns:1fr}
 .product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .bite-photo{float:none;width:100%;max-width:none;margin:0 0 8px;aspect-ratio:16/9}
 .photo-credit{width:100%;max-width:none;margin:0 0 16px}
 .education-second{clear:both}
 .footer-nav{flex-direction:column;gap:12px}
}
@media(max-width:520px){
 .product-grid{grid-template-columns:minmax(0,1fr)}
 .product-card{max-width:360px;margin-inline:auto}
 .brand{min-width:0}
 .tagline{font-size:.8rem}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}

